function BookSpineLabelPrinterMaker.init() BookSpineLabelPrinterMaker.ironStock=14; BookSpineLabelPrinterMaker.bronzeStock=12; BookSpineLabelPrinterMaker.woodStock=14; BookSpineLabelPrinterMaker.leatherStock=8; BookSpineLabelPrinterMaker.silverStock=8; BookSpineLabelPrinterMaker.goldStock=6; BookSpineLabelPrinterMaker.jewelStock=4; BookSpineLabelPrinterMaker.pearlStock=4; BookSpineLabelPrinterMaker.productStock={}; BookSpineLabelPrinterMaker.buildings={}; BookSpineLabelPrinterMaker.maker=nil; BookSpineLabelPrinterMaker.activeMaking={}; BookSpineLabelPrinterMaker.totalProducts=0; BookSpineLabelPrinterMaker.dayTimer=0; print("[BookSpineLabelPrinterMaker] Royal Book Spine Label Printer Maker System initialized (6 products, 4 buildings)") end
function BookSpineLabelPrinterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookSpineLabelPrinterMaker.maker={name=n or ("Tiskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tiskar najet: %s (spretnost: %d)",BookSpineLabelPrinterMaker.maker.name,s),"success") end; return true end
function BookSpineLabelPrinterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookSpineLabelPrinterMaker.build(id) local ok,e=BookSpineLabelPrinterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookSpineLabelPrinterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookSpineLabelPrinterMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookSpineLabelPrinterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookSpineLabelPrinterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookSpineLabelPrinterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookSpineLabelPrinterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookSpineLabelPrinterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookSpineLabelPrinterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookSpineLabelPrinterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookSpineLabelPrinterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookSpineLabelPrinterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookSpineLabelPrinterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookSpineLabelPrinterMaker.buildings==0 then return false,"Potrebna tiskarska delavnica" end; if not BookSpineLabelPrinterMaker.maker then return false,"Potreben tiskar" end; return true end
function BookSpineLabelPrinterMaker.make(pt,qty) qty=qty or 1; local ok,e=BookSpineLabelPrinterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookSpineLabelPrinterMaker.ironStock=BookSpineLabelPrinterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookSpineLabelPrinterMaker.bronzeStock=BookSpineLabelPrinterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookSpineLabelPrinterMaker.woodStock=BookSpineLabelPrinterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookSpineLabelPrinterMaker.leatherStock=BookSpineLabelPrinterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookSpineLabelPrinterMaker.silverStock=BookSpineLabelPrinterMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookSpineLabelPrinterMaker.goldStock=BookSpineLabelPrinterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookSpineLabelPrinterMaker.jewelStock=BookSpineLabelPrinterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookSpineLabelPrinterMaker.pearlStock=BookSpineLabelPrinterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookSpineLabelPrinterMaker.maker then t=math.max(1,t-math.floor(BookSpineLabelPrinterMaker.maker.skill/13)) end; table.insert(BookSpineLabelPrinterMaker.activeMaking,{id="bookspinelabelprinter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookSpineLabelPrinterMaker.completeMaking(m) local q=1.0+(BookSpineLabelPrinterMaker.getQualityBonus()/100); if BookSpineLabelPrinterMaker.maker then q=q+(BookSpineLabelPrinterMaker.maker.skill/140) end; q=math.min(2.5,q); BookSpineLabelPrinterMaker.productStock[m.productType]=(BookSpineLabelPrinterMaker.productStock[m.productType] or 0)+m.quantity; BookSpineLabelPrinterMaker.totalProducts=BookSpineLabelPrinterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookSpineLabelPrinterMaker.maker then BookSpineLabelPrinterMaker.maker.itemsMade=BookSpineLabelPrinterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookSpineLabelPrinterMaker.maker.skill=math.min(100,BookSpineLabelPrinterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tisk izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookspinelabelprinter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookSpineLabelPrinterMaker.update(dt) if not _G.state then return end; BookSpineLabelPrinterMaker.dayTimer=BookSpineLabelPrinterMaker.dayTimer+dt; if BookSpineLabelPrinterMaker.dayTimer>=30 then BookSpineLabelPrinterMaker.dayTimer=0; for i=#BookSpineLabelPrinterMaker.activeMaking,1,-1 do local m=BookSpineLabelPrinterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookSpineLabelPrinterMaker.completeMaking(m); table.remove(BookSpineLabelPrinterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookSpineLabelPrinterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookSpineLabelPrinterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookSpineLabelPrinterMaker.getStats() return {ironStock=BookSpineLabelPrinterMaker.ironStock,bronzeStock=BookSpineLabelPrinterMaker.bronzeStock,woodStock=BookSpineLabelPrinterMaker.woodStock,leatherStock=BookSpineLabelPrinterMaker.leatherStock,silverStock=BookSpineLabelPrinterMaker.silverStock,goldStock=BookSpineLabelPrinterMaker.goldStock,jewelStock=BookSpineLabelPrinterMaker.jewelStock,pearlStock=BookSpineLabelPrinterMaker.pearlStock,productStock=BookSpineLabelPrinterMaker.productStock,numBuildings=#BookSpineLabelPrinterMaker.buildings,hasMaker=BookSpineLabelPrinterMaker.maker~=nil,makerName=BookSpineLabelPrinterMaker.maker and BookSpineLabelPrinterMaker.maker.name or "—",makerSkill=BookSpineLabelPrinterMaker.maker and BookSpineLabelPrinterMaker.maker.skill or 0,activeMaking=#BookSpineLabelPrinterMaker.activeMaking,totalProducts=BookSpineLabelPrinterMaker.totalProducts} end
